sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float grainSize;
uniform float speed;
float hash(float3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }

half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float a = src.a;
    if (a < 1e-6) return src;
    half3 rgb = src.rgb / a;
    float frame = mod(floor((time + 0.000999) * max(speed, 0.0) * 30.0), 4096.0);
    float cell = exp2((clamp(grainSize, 1.0, 8.0) - 4.0) * 0.5);
    float2 p = coord / max(cell, 1.0) - 0.5;
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float noise = mix(mix(hash(float3(i, frame)), hash(float3(i + float2(1.0, 0.0), frame)), f.x),
                      mix(hash(float3(i + float2(0.0, 1.0), frame)), hash(float3(i + 1.0, frame)), f.x), f.y);
    noise = 0.5 + (noise - 0.5) * min(cell, 1.0);
    float grain = (noise * 2.0 - 1.0) * amount;
    rgb += grain;
    rgb = clamp(rgb, half3(0.0), half3(1.0));
    return half4(rgb * a, a);
}
